INSERT INTO gold_texts (gold, lang, title, text) VALUES
  ('bdelloid-rotifers', 'de', '24.000 Jahre im Eis und dann einfach weitermachen', 'Russische Forschende haben sich durch sibirischen Permafrost gebohrt und winzige mehrzellige Tiere herausgeholt: bdelloide Rädertierchen. Laut Radiokarbondatierung war die Erde, aus der sie stammten, etwa 24.000 Jahre alt. Nach dem Auftauen wurde ein Rädertierchen der Gattung Adineta wieder aktiv und machte direkt, was es am besten kann: sich klonen. Diese Rädertierchen vermehren sich durch Jungfernzeugung, ganz ohne Partner. Das Team hat den Fund 2021 in Current Biology veröffentlicht und nennt ihn den bisher härtesten Beweis dafür, dass ein mehrzelliges Tier Zehntausende Jahre in einer Art Scheintod überstehen kann.'),
  ('bdelloid-rotifers', 'en', '24,000 Years on Ice, Then Back to Business', 'Russian researchers drilled into Siberian permafrost and pulled out tiny multicellular animals called bdelloid rotifers. Radiocarbon dating put the soil they came from at about 24,000 years old. After thawing, a rotifer of the genus Adineta woke up and did what it does best: it cloned itself. These rotifers reproduce by parthenogenesis, no partner needed. The team reported the find in Current Biology in 2021 and called it the hardest proof so far that a multicellular animal can sit out tens of thousands of years in suspended animation.');
INSERT INTO gold_sources (gold, pos, label, url) VALUES
  ('bdelloid-rotifers', 1, 'ScienceDaily: Arctic rotifer lives after 24,000 years in a frozen state', 'https://www.sciencedaily.com/releases/2021/06/210607161159.htm'),
  ('bdelloid-rotifers', 2, 'Sci.News: Frozen Microscopic Animals Brought Back to Life after 24,000 Years', 'https://www.sci.news/biology/frozen-bdelloid-rotifers-siberian-permafrost-09745.html'),
  ('bdelloid-rotifers', 3, 'Current Biology: A living bdelloid rotifer from 24,000-year-old Arctic permafrost', 'https://www.cell.com/current-biology/fulltext/S0960-9822(21)00624-2');
